methods.source:
def _rec_names_search(self):
    if self.env.context.get("sale_show_partner_name"):
        return ["name", "partner_id.name"]
    return ["name"]

def _compute_display_name(self):
    super()._compute_display_name()
    for order in self:
        order_label = order.name
        if order.client_order_ref:
            order_label = f"{order_label} ({order.client_order_ref})"

        if self.env.context.get("sale_show_partner_name") and order.partner_id.name:
            if self.env.context.get("formatted_display_name"):
                order.display_name = f"{order_label} \t --{order.partner_id.name}--"
            else:
                order.display_name = f"{order_label} - {order.partner_id.name}"
        else:
            order.display_name = order_label

def _compute_has_archived_products(self):
    for order in self:
        order.has_archived_products = any(
            not product.active for product in order.order_line.product_id
        )

def _compute_require_signature(self):
    for order in self:
        order.require_signature = order.company_id.portal_confirmation_sign

def _compute_prepayment_percent(self):
    for order in self:
        if order.company_id.portal_confirmation_pay:
            order.prepayment_percent = order.company_id.prepayment_percent
        else:
            order.prepayment_percent = 0.0

def _compute_prepayment_amount(self):
    for order in self:
        order.prepayment_amount = order.prepayment_percent * order.amount_total

def _inverse_prepayment_amount(self):
    for order in self:
        if order.amount_total:
            order.prepayment_percent = order.prepayment_amount / order.amount_total
        else:
            order.prepayment_percent = 0.0

def _compute_validity_date(self):
    today = fields.Date.context_today(self)
    for order in self:
        days = order.company_id.quotation_validity_days
        if days > 0:
            order.validity_date = today + timedelta(days)
        else:
            order.validity_date = False

def _compute_note(self):
    use_invoice_terms = (
        self.env["ir.config_parameter"].sudo().get_bool("account.use_invoice_terms")
    )
    if not use_invoice_terms:
        return
    for order in self:
        if order.state != "draft":
            continue
        order = order.with_company(order.company_id)
        if order.terms_type == "html" and order.env.company.invoice_terms_html:
            baseurl = html_keep_url(order._get_note_url() + "/terms")
            context = {"lang": order.partner_id.lang or self.env.user.lang}
            order.note = order.env._("Terms & Conditions: %s", baseurl)
            del context
        elif not is_html_empty(order.env.company.invoice_terms):
            if order.partner_id.lang:
                order = order.with_context(lang=order.partner_id.lang)
            order.note = order.env.company.invoice_terms

def _inverse_note(self):
    for sales_order in self:
        sales_order.note = self.env["account.move"]._set_links_to_new_tab(sales_order.note)

def _compute_partner_invoice_id(self):
    for order in self:
        order.partner_invoice_id = (
            order.partner_id.address_get(["invoice"])["invoice"] if order.partner_id else False
        )

def _compute_partner_shipping_id(self):
    for order in self:
        order.partner_shipping_id = (
            order.partner_id.address_get(["delivery"])["delivery"]
            if order.partner_id
            else False
        )

def _compute_fiscal_position_id(self):
    cache = {}
    for order in self:
        if not order.partner_id:
            order.fiscal_position_id = False
            continue
        key = (order.company_id.id, order.partner_id.id, order.partner_shipping_id.id)
        if key not in cache:
            cache[key] = (
                self
                .env["account.fiscal.position"]
                .with_company(order.company_id)
                ._get_fiscal_position(order.partner_id, order.partner_shipping_id)
                .id
            )
        order.fiscal_position_id = cache[key]

def _compute_payment_term_id(self):
    for order in self:
        order = order.with_company(order.company_id)
        order.payment_term_id = order.partner_id.property_payment_term_id

def _compute_preferred_payment_method_line_id(self):
    for order in self:
        order = order.with_company(order.company_id)
        order.preferred_payment_method_line_id = (
            order.partner_id.property_inbound_payment_method_line_id
        )

def _compute_pricelist_id(self):
    for order in self:
        if order.state != "draft":
            continue
        if not order.partner_id:
            order.pricelist_id = False
            continue
        order = order.with_company(order.company_id)
        order.pricelist_id = order.partner_id.property_product_pricelist

def _compute_currency_id(self):
    for order in self:
        order.currency_id = order.pricelist_id.currency_id or order.company_id.currency_id

def _compute_currency_rate(self):
    for order in self:
        order.currency_rate = self.env["res.currency"]._get_conversion_rate(
            from_currency=order.company_id.currency_id,
            to_currency=order.currency_id,
            company=order.company_id,
            date=(order.date_order or fields.Datetime.now()).date(),
        )

def _compute_has_active_pricelist(self):
    for order in self:
        order.has_active_pricelist = bool(
            self.env["product.pricelist"].search(
                [("company_id", "in", (False, order.company_id.id)), ("active", "=", True)],
                limit=1,
            )
        )

def _compute_user_id(self):
    for order in self:
        if order.partner_id and not (order._origin.id and order.user_id):
            # Recompute the salesman on partner change
            #   * if partner is set (is required anyway, so it will be set sooner or later)
            #   * if the order is not saved or has no salesman already
            order.user_id = (
                order.partner_id.user_id
                or order.partner_id.commercial_partner_id.user_id
                or (self.env.user.has_group("sales_team.group_sale_salesman") and self.env.user)
            )

def _compute_team_id(self):
    cached_teams = {}
    for order in self:
        default_team_id = order._default_team_id()
        user_id = order.user_id.id
        company_id = order.company_id.id
        key = (default_team_id, user_id, company_id)
        if key not in cached_teams:
            cached_teams[key] = (
                self
                .env["crm.team"]
                .with_context(default_team_id=default_team_id)
                ._get_default_team_id(
                    user_id=user_id,
                    domain=self.env["crm.team"]._check_company_domain(company_id),
                )
            )
        order.team_id = cached_teams[key]

def _compute_incoterm(self):
    for order in self:
        order.incoterm = order.partner_id.incoterm_id or order.company_id.incoterm_id

def _compute_incoterm_location(self):
    for order in self:
        order.incoterm_location = order.partner_id.incoterm_location

def _compute_transaction_count(self):
    if not self.env.user.has_group("account.group_account_invoice"):
        self.transaction_count = 0
        return
    for order in self:
        order.transaction_count = len(order.transaction_ids)

def _compute_invoice_status(self):
    """
    Compute the invoice status of a SO. Possible statuses:
    - no: if the SO is not in status 'sale' or 'done', we consider that there is nothing to
      invoice. This is also the default value if the conditions of no other status is met.
    - to invoice: if any SO line is 'to invoice', the whole SO is 'to invoice'
    - invoiced: if all SO lines are invoiced, the SO is invoiced.
    - upselling: if all SO lines are invoiced or upselling, the status is upselling.
    """
    confirmed_orders = self.filtered(lambda so: so.state == "sale")
    (self - confirmed_orders).invoice_status = "no"
    closed_orders = confirmed_orders.filtered("invoicing_closed")
    closed_orders.invoice_status = "invoiced"
    orders_to_compute = confirmed_orders - closed_orders
    if not orders_to_compute:
        return
    lines_domain = [("is_downpayment", "=", False), ("display_type", "=", False)]
    line_invoice_status_all = [
        (order.id, invoice_status)
        for order, invoice_status in self.env["sale.order.line"]._read_group(
            lines_domain + [("order_id", "in", orders_to_compute.ids)],
            ["order_id", "invoice_status"],
        )
    ]
    for order in orders_to_compute:
        line_invoice_status = [d[1] for d in line_invoice_status_all if d[0] == order.id]
        if any(invoice_status == "to invoice" for invoice_status in line_invoice_status):
            if any(invoice_status == "no" for invoice_status in line_invoice_status):
                # If only discount/delivery/promotion lines can be invoiced, the SO should not
                # be invoiceable.
                invoiceable_domain = lines_domain + [("invoice_status", "=", "to invoice")]
                invoiceable_lines = order.order_line.filtered_domain(invoiceable_domain)
                special_lines = invoiceable_lines.filtered(
                    lambda sol: not sol._can_be_invoiced_alone()
                )
                if invoiceable_lines == special_lines:
                    order.invoice_status = "no"
                else:
                    order.invoice_status = "to invoice"
            else:
                order.invoice_status = "to invoice"
        elif line_invoice_status and all(
            invoice_status == "invoiced" for invoice_status in line_invoice_status
        ):
            order.invoice_status = "invoiced"
        elif line_invoice_status and all(
            invoice_status in ("invoiced", "upselling")
            for invoice_status in line_invoice_status
        ):
            order.invoice_status = "upselling"
        else:
            order.invoice_status = "no"

def _compute_authorized_transaction_ids(self):
    for trans in self:
        trans.authorized_transaction_ids = trans.transaction_ids.filtered(
            lambda t: t.state == "authorized"
        )
        trans.has_authorized_transaction_ids = bool(trans.authorized_transaction_ids)

def _compute_amount_paid(self):
    """Sum of the amount paid through all transactions for this SO."""
    for order in self:
        order.amount_paid = sum(
            tx.amount for tx in order.transaction_ids if tx.state in ("authorized", "done")
        )

def _compute_amount_unpaid(self):
    for order in self:
        online_payments_invoices = order.transaction_ids.filtered(
            lambda tx: tx.state in {"authorized", "done"}
        ).invoice_ids
        offline_invoice_lines = order.order_line.invoice_lines.filtered(
            lambda line: (
                line.parent_state in {"draft", "posted"}
                and line.move_id not in online_payments_invoices
            )
        )
        offline_invoice_amount = sum(
            math.copysign(line.price_total, -line.balance) for line in offline_invoice_lines
        )

        order.amount_unpaid = max(
            order.amount_total - order.amount_paid - offline_invoice_amount, 0
        )

def _compute_delivery_status(self):
    for order in self:
        lines_to_deliver = order.order_line.filtered(
            lambda line: line.product_id.type == "consu"
        )
        if order.state != "sale" or not lines_to_deliver:
            order.delivery_status = False
        elif all(
            line.qty_delivered >= line.product_uom_qty
            if line.product_uom_qty > 0
            else line.qty_delivered <= line.product_uom_qty
            for line in lines_to_deliver
        ):
            order.delivery_status = "full"
        elif any(line.qty_delivered for line in lines_to_deliver):
            order.delivery_status = "partial"
        else:
            order.delivery_status = "pending"

def _compute_duplicated_order_ids(self):
    draft_orders = self.filtered(lambda o: o.state == "draft")
    order_to_duplicate_orders = draft_orders._fetch_duplicate_orders()
    for order in draft_orders:
        order.duplicated_order_ids = [Command.set(order_to_duplicate_orders.get(order.id, []))]
    (self - draft_orders).duplicated_order_ids = False

def _compute_expected_date(self):
    """For service and combo (non-goods) products, we avoid computing the expected date.

    This method is extended in sale_stock to take the picking_policy of SO into account.
    """
    self.mapped("order_line")  # Prefetch indication
    for order in self:
        if order.state == "cancel":
            order.expected_date = False
            continue
        dates_list = order.order_line.filtered(
            lambda line: (
                (not line.product_id or line.product_id.type == "consu")
                and not line.display_type
                and not line._is_delivery()
            )
        ).mapped(lambda line: line and line._expected_date())
        if dates_list:
            order.expected_date = order._select_expected_date(dates_list)
        else:
            order.expected_date = False

def _select_expected_date(self, expected_dates):
    self.ensure_one()
    return min(expected_dates)

def _compute_is_expired(self):
    today = fields.Date.context_today(self)
    for order in self:
        order.is_expired = (
            order.state in ("draft", "sent")
            and order.validity_date
            and order.validity_date < today
        )

def _search_is_unfulfilled(self, operator, value):  # noqa: PLR6301
    if operator not in {"=", "!="}:
        return NotImplemented

    if (operator == "=" and value) or (operator == "!=" and not value):
        effective_operator = "any"
    else:
        effective_operator = "not any"

    line_domain = Domain.custom(
        to_sql=lambda table: SQL("%s < %s", table.qty_delivered, table.product_uom_qty)
    ) & Domain([("product_id.product_tmpl_id.type", "!=", "service")])
    return Domain("state", "=", "sale") & Domain("order_line", effective_operator, line_domain)

def _compute_tax_country_id(self):
    for record in self:
        if record.fiscal_position_id.foreign_vat:
            record.tax_country_id = record.fiscal_position_id.country_id
        else:
            record.tax_country_id = record.company_id.account_fiscal_country_id

def _compute_amount_to_invoice(self):
    for order in self:
        order.amount_to_invoice = sum(order.order_line.mapped("amount_to_invoice"))

def _compute_amount_invoiced(self):
    for order in self:
        order.amount_invoiced = sum(order.order_line.mapped("amount_invoiced"))

def _compute_partner_credit_warning(self):
    for order in self:
        order = order.with_company(order.company_id)
        order.partner_credit_warning = ""
        show_warning = (
            order.state in ("draft", "sent") and order.company_id.account_use_credit_limit
        )
        if show_warning:
            order.partner_credit_warning = self.env[
                "account.move"
            ]._build_credit_warning_message(
                order.sudo(),  # ensure access to `credit` & `credit_limit` fields
                current_amount=(order.amount_total / order.currency_rate),
            )

def _compute_extra_total_fields(self):
    for order in self:
        basic_group = {"sequence": 1, "name": "basic", "lines": []}
        _excl, incl = order._get_advantages()
        if incl:
            basic_group["lines"].append({
                "label": self.env._("Total Advantage"),
                "value": abs(incl),
            })

        order.extra_total_fields = [basic_group]

def _compute_type_name(self):
    for record in self:
        if record.state in ("draft", "sent", "cancel"):
            record.type_name = record.env._("Quotation")
        else:
            record.type_name = record.env._("Sales Order")

def _compute_access_url(self):
    super()._compute_access_url()
    for order in self:
        order.access_url = f"/my/orders/{order.id}"

def _compute_sale_warning_text(self):
    if not self.env.user.has_group("sale.group_warning_sale"):
        self.sale_warning_text = ""
        return
    for order in self:
        warnings = OrderedSet()
        if partner_msg := order.partner_id.sale_warn_msg:
            warnings.add(
                (order.partner_id.name or order.partner_id.display_name) + " - " + partner_msg
            )
        if partner_parent_msg := order.partner_id.parent_id.sale_warn_msg:
            parent = order.partner_id.parent_id
            warnings.add((parent.name or parent.display_name) + " - " + partner_parent_msg)
        for line in order.order_line:
            if product_msg := line.sale_line_warn_msg:
                warnings.add(line.product_id.display_name + " - " + product_msg)
        order.sale_warning_text = "\n".join(warnings)

def _compute_delivery_date(self):
    for order in self:
        order.delivery_date = order.commitment_date or order.expected_date

def _compute_has_overages(self):
    for order in self:
        order.has_overages = any(line.qty_overage for line in order.order_line)

def _compute_document_tax_mode(self):
    for order in self:
        if not order.document_tax_mode:
            company = order.company_id or self.env.company
            order.document_tax_mode = company.account_price_include

def _check_order_line_company_id(self):
    for order in self:
        invalid_companies = order.order_line.product_id.company_id.filtered(
            lambda c: order.company_id not in c._accessible_branches()
        )
        if invalid_companies:
            bad_products = order.order_line.product_id.filtered(
                lambda p: p.company_id and p.company_id in invalid_companies
            )
            raise ValidationError(
                order.env._(
                    "Your quotation contains products from company %(product_company)s whereas"
                    " your quotation belongs to company %(quote_company)s. \nPlease change the"
                    " company of your quotation or remove the products from other companies"
                    "(%(bad_products)s).",
                    product_company=", ".join(invalid_companies.sudo().mapped("display_name")),
                    quote_company=order.company_id.display_name,
                    bad_products=", ".join(bad_products.mapped("display_name")),
                )
            )

def _check_prepayment_percent(self):
    for order in self:
        if not (0 <= order.prepayment_percent <= 1.0):
            raise ValidationError(
                order.env._("Prepayment percentage must be a valid percentage.")
            )

def onchange(self, values, field_names, fields_spec):
    self_with_context = self
    if not field_names:
        self_with_context = self.with_context(
            # Some warnings should not be displayed for the first onchange
            sale_onchange_first_call=True,
            # invoice & delivery address with higher `customer_rank` should take priority
            res_partner_search_mode="customer",
        )
    return super(SaleOrder, self_with_context).onchange(values, field_names, fields_spec)

def _onchange_commitment_date(self):
    """Warn if the commitment dates is sooner than the expected date."""
    if (
        self.commitment_date
        and self.expected_date
        and self.commitment_date < self.expected_date
    ):
        return {
            "warning": {
                "title": self.env._("Requested date is too soon."),
                "message": self.env._(
                    "The delivery date is sooner than the expected date."
                    " You may be unable to honor the delivery date."
                ),
            }
        }

def _onchange_company_id_warning(self):
    if self.env.context.get("sale_onchange_first_call"):
        return None
    if self.order_line and self.state == "draft":
        return {
            "warning": {
                "title": self.env._("Warning for the change of your quotation's company"),
                "message": self.env._(
                    "Changing the company of an existing quotation might need some "
                    "manual adjustments in the details of the lines. You might "
                    "consider updating the prices."
                ),
            }
        }

def _onchange_company_id(self):
    for order in self:
        # This can't be caught by a python constraint as it is only triggered at save
        # and a compute method needs this data to be set correctly before saving
        if not order.company_id:
            raise ValidationError(
                order.env._(
                    "The company is required, please select one before making any other changes"
                    " to the sale order."
                )
            )

def _onchange_fpos_id_recompute_taxes(self):
    if self.order_line:
        self._recompute_taxes()

def _onchange_pricelist_id_recompute_prices(self):
    # DO NOT ADD the `pricelist_id` as dependency to the order lines compute methods as it
    # would trigger unwanted recomputations as the orm recomputes all depending fields
    # regardless of whether the field was effectively modified.
    if self.order_line and not self.env.context.get("sale_onchange_first_call"):
        self._recompute_prices()

def _onchange_prepayment_amount(self):
    if self.amount_total:
        self.prepayment_percent = self.prepayment_amount / self.amount_total

def _onchange_order_line(self):
    linked_lines_by_line = self.order_line._get_linked_lines_by_line()
    for line in self.order_line:
        if line.display_type == "line_subsection" and not line.parent_id:
            line.display_type = "line_section"
        combo_item_lines = linked_lines_by_line[line].filtered("combo_item_id")
        if line.product_template_id.type != "combo":
            if combo_item_lines:
                # Delete any linked combo item lines if the line's product is no longer a combo
                # product.
                self.order_line = [
                    Command.delete(linked_line.id) for linked_line in combo_item_lines
                ]
        elif line.selected_combo_items:
            selected_combo_items = json.loads(line.selected_combo_items)
            if selected_combo_items and len(selected_combo_items) != len(
                line.product_template_id.sudo().combo_ids
            ):
                raise ValidationError(
                    line.env._(
                        "The number of selected combo items must match the number of available"
                        " combo choices."
                    )
                )

            # Delete any existing combo item lines.
            delete_commands = [
                Command.delete(linked_line.id) for linked_line in combo_item_lines
            ]
            # Create a new combo item line for each selected combo item.
            create_commands = [
                Command.create({
                    "product_id": combo_item["product_id"],
                    "product_uom_qty": line.product_uom_qty,
                    "combo_item_id": combo_item["combo_item_id"],
                    "product_no_variant_attribute_value_ids": [
                        Command.set(combo_item["no_variant_attribute_value_ids"])
                    ],
                    "product_custom_attribute_value_ids": [Command.clear()]
                    + [
                        Command.create(attribute_value)
                        for attribute_value in combo_item["product_custom_attribute_values"]
                    ],
                    # Combo item lines should come directly after their combo product line.
                    "sequence": line.sequence + item_index + 1,
                    # If the linked line exists in DB, populate linked_line_id, otherwise
                    # populate linked_virtual_id.
                    "linked_line_id": line.id if line._origin else False,
                    "linked_virtual_id": line.virtual_id if not line._origin else False,
                })
                for item_index, combo_item in enumerate(selected_combo_items)
            ]
            # Shift any lines coming after the combo product line so that the combo item lines
            # come first.
            update_commands = [
                Command.update(
                    order_line.id, {"sequence": order_line.sequence + len(selected_combo_items)}
                )
                for order_line in self.order_line
                if order_line.sequence > line.sequence
            ]

            # Clear `selected_combo_items` to avoid applying the same changes multiple times.
            line.selected_combo_items = False
            self.order_line = delete_commands + create_commands + update_commands
        elif (
            combo_item_lines
            # Only update the combo item lines if the line's combo choices haven't changed.
            and combo_item_lines.combo_item_id.combo_id == line.product_template_id.combo_ids
        ):
            lines_to_sync = combo_item_lines.filtered(
                lambda cil: (
                    cil.product_uom_qty != line.product_uom_qty or cil.discount != line.discount
                )
            )
            if lines_to_sync:
                lines_to_sync.update({
                    "product_uom_qty": line.product_uom_qty,
                    "discount": line.discount,
                })

def create(self, vals_list):
    for vals in vals_list:
        if vals.get("name", self.env._("New")) == self.env._("New"):
            seq_date = (
                fields.Datetime.context_timestamp(
                    self, fields.Datetime.to_datetime(vals["date_order"])
                )
                if "date_order" in vals
                else None
            )
            vals["name"] = self.env["ir.sequence"].with_company(
                vals.get("company_id")
            ).next_by_code("sale.order", sequence_date=seq_date) or self.env._("New")

    return super().create(vals_list)

def _get_copiable_order_lines(self):
    """Return the order lines that can be copied to a new order."""
    return self.order_line.filtered(lambda sol: not sol.is_downpayment)

def copy_data(self, default=None):
    default = dict(default or {})
    default_has_no_order_line = "order_line" not in default
    default.setdefault("order_line", [])
    vals_list = super().copy_data(default=default)
    if default_has_no_order_line:
        for order, vals in zip(self, vals_list):
            vals["order_line"] = [
                Command.create(line_vals)
                for line_vals in order._get_copiable_order_lines().copy_data()
            ]
    return vals_list

def _unlink_except_draft_or_cancel(self):
    for order in self:
        if order.state not in ("draft", "cancel"):
            raise UserError(
                order.env._(
                    "You can not delete a sent quotation or a confirmed sales order."
                    " You must first cancel it."
                )
            )

def write(self, vals):
    if "pricelist_id" in vals and any(so.state == "sale" for so in self):
        raise UserError(self.env._("You cannot change the pricelist of a confirmed order !"))
    return super().write(vals)

def action_open_discount_wizard(self):
    self.ensure_one()
    return {
        "name": self.env._("Discount"),
        "type": "ir.actions.act_window",
        "res_model": "sale.order.discount",
        "views": [(False, "form")],
        "view_mode": "form",
        "target": "new",
    }

def action_draft(self):
    orders = self.filtered(lambda s: s.state in ["cancel", "sent"])
    return orders.write({
        "state": "draft",
        "signature": False,
        "signed_by": False,
        "signed_on": False,
    })

def _find_mail_template(self):
    """Get the appropriate mail template for the current sales order based on its state.

    If the SO is confirmed, we return the mail template for the sale confirmation.
    Otherwise, we return the quotation email template.

    :return: The correct mail template based on the current status
    :rtype: record of `mail.template` or `None` if not found
    """
    self.ensure_one()
    if self.env.context.get("proforma"):
        return self.env.ref("sale.email_template_proforma", raise_if_not_found=False)
    if self.state != "sale":
        return self.env.ref("sale.email_template_edi_sale", raise_if_not_found=False)
    return self._get_confirmation_template()

def _get_confirmation_template(self):
    """Get the mail template sent on SO confirmation (or for confirmed SO's).

    :return: `mail.template` record or None if default template wasn't found
    """
    self.ensure_one()
    default_confirmation_template_id = (
        self.env["ir.config_parameter"].sudo().get_int("sale.default_confirmation_template")
    )
    default_confirmation_template = (
        self.env["mail.template"].browse(default_confirmation_template_id).exists()
    )
    if default_confirmation_template:
        return default_confirmation_template
    return self.env.ref("sale.mail_template_sale_confirmation", raise_if_not_found=False)

def _should_be_locked(self):
    self.ensure_one()
    # Public user can confirm SO, so we check the group on any record creator.
    return self.env["res.groups"]._is_feature_enabled("sale.group_auto_done_setting")

def _confirmation_error_message(self):
    """Return whether order can be confirmed or not if not then return error message."""
    self.ensure_one()
    if self.state not in {"draft", "sent"}:
        return self.env._("Some orders are not in a state requiring confirmation.")

    return False

def _send_payment_succeeded_for_order_mail(self):
    """Send a mail to the SO customer to inform them that a payment has been initiated.

    :return: None
    """
    mail_template = self.env.ref(
        "sale.mail_template_sale_payment_executed", raise_if_not_found=False
    )
    for order in self:
        order._send_order_notification_mail(mail_template)

def action_close_invoicing(self):
    """Mark sales orders as manually closed for invoicing."""
    draft_orders = self.filtered(lambda o: o.state != "sale")
    if draft_orders:
        orders_name = ", ".join(draft_orders.mapped("name"))
        raise UserError(
            self.env._(
                "Cannot close %(orders_name)s: must be in 'Sales Order' state.",
                orders_name=orders_name,
            )
        )
    orders_to_close = self.filtered(lambda o: not o.invoicing_closed)
    self.invoicing_closed = True
    orders_to_close._message_log_batch(
        bodies={order.id: self.env._("Invoicing closed") for order in orders_to_close}
    )

def action_reopen_order(self):
    """Reopen invoicing for manually closed sales orders."""
    orders_to_reopen = self.filtered("invoicing_closed")
    orders_to_reopen.invoicing_closed = False
    orders_to_reopen._message_log_batch(
        bodies={order.id: self.env._("Invoicing reopened") for order in orders_to_reopen}
    )

def action_cancel(self):
    """Cancel sales order and related draft invoices."""
    if any(order.locked for order in self):
        raise UserError(self.env._("You cannot cancel a locked order. Please unlock it first."))
    return self._action_cancel()

def _action_cancel(self):
    inv = self.invoice_ids.filtered(lambda inv: inv.state == "draft")
    inv.button_cancel()
    return self.write({"state": "cancel"})

def action_preview_sale_order(self):
    self.ensure_one()
    url = urljoin(self.get_base_url(), self.get_portal_url())
    return {"type": "ir.actions.act_url", "target": "new", "url": url}

def _recompute_taxes(self):
    lines_to_recompute = self.order_line.filtered(lambda line: not line.display_type)

    lines_to_recompute.with_context(recompute_unit_price_on_tax_change=True)._compute_tax_ids()

def action_open_business_doc(self):
    self.ensure_one()
    return {
        "name": self.env._("Order"),
        "type": "ir.actions.act_window",
        "res_model": "sale.order",
        "res_id": self.id,
        "views": [(False, "form")],
    }

def action_view_invoice(self, invoices=False):
    if not invoices:
        invoices = self.mapped("invoice_ids")
    action = self.env["ir.actions.actions"]._for_xml_id("account.action_move_out_invoice_type")
    if len(invoices) > 1:
        action["domain"] = [("id", "in", invoices.ids)]
    elif len(invoices) == 1:
        form_view = [(self.env.ref("account.view_move_form").id, "form")]
        if "views" in action:
            action["views"] = form_view + [
                (state, view) for state, view in action["views"] if view != "form"
            ]
        else:
            action["views"] = form_view
        action["res_id"] = invoices.id
    else:
        action = {"type": "ir.actions.act_window_close"}

    context = {"default_move_type": "out_invoice"}
    if len(self) == 1:
        context.update({
            "default_partner_id": self.partner_id.id,
            "default_partner_shipping_id": self.partner_shipping_id.id,
            "default_invoice_payment_term_id": self.payment_term_id.id
            or self.partner_id.property_payment_term_id.id
            or self
            .env["account.move"]
            .default_get(["invoice_payment_term_id"])
            .get("invoice_payment_term_id"),
        })
    action["context"] = context
    return action

def action_view_payment_transaction(self):
    action = self.env["ir.actions.act_window"]._for_xml_id("payment.action_payment_transaction")
    if len(self.transaction_ids) == 1:
        action["view_mode"] = "form"
        action["res_id"] = self.transaction_ids.id
        action["views"] = []
    else:
        action["domain"] = [("id", "in", self.transaction_ids.ids)]
    return action

def _get_update_prices_lines(self):
    """Determine the lines whose prices should be recomputed on pricelist change."""
    return self.order_line.filtered(lambda line: not line.display_type)

def _discard_tracking(self):
    self.ensure_one()
    return self.state == "draft" and request and request.env.context.get("catalog_update")

def _track_finalize(self):
    """Override of `mail` to prevent logging changes when the SO is in a draft state."""
    if (
        len(self) == 1
        # The method _track_finalize is sometimes called too early or too late and it
        # might cause a desynchronization with the cache, thus this condition is needed.
        and self.id in self._fields["state"]._get_cache(self.env)
        and self._discard_tracking()
    ):
        self._track_clear()
    return super()._track_finalize()

def message_post(self, **kwargs):
    if self.env.context.get("mark_so_as_sent"):
        self.filtered(lambda o: o.state == "draft").with_context(tracking_disable=True).write({
            "state": "sent"
        })
        kwargs["notify_author_mention"] = kwargs.get("notify_author_mention", True)
    return super().message_post(**kwargs)

def _notify_get_recipients_groups(self, message, model_description):
    # Give access button to users and portal customer as portal is integrated
    # in sale. Customer and portal group have probably no right to see
    # the document so they don't have the access button.
    groups = super()._notify_get_recipients_groups(message, model_description)
    if not self:
        return groups

    self.ensure_one()
    if self.env.context.get("proforma"):
        for group in [
            g for g in groups if g[0] in ("portal_customer", "portal", "follower", "customer")
        ]:
            group[2]["has_button_access"] = False
        return groups

    # portal customers have full access (existence not granted, depending on partner_id)
    try:
        customer_portal_group = next(group for group in groups if group[0] == "portal_customer")
    except StopIteration:
        pass
    else:
        access_opt = customer_portal_group[2].setdefault("button_access", {})
        if self.state in ("draft", "sent"):
            access_opt["title"] = self.env._("View Quotation")

    return groups

def _track_log_get_default_subtype(self, track_init_values):
    self.ensure_one()
    if "state" in track_init_values and self.state == "sale":
        return self.env.ref("sale.mt_order_confirmed")
    if "state" in track_init_values and self.state == "sent":
        return self.env.ref("sale.mt_order_sent")
    return super()._track_log_get_default_subtype(track_init_values)

def _get_model_description(self, model_name):
    if not self:
        return super()._get_model_description(model_name)
    return self.type_name

def _force_lines_to_invoice_policy_order(self):
    """Force the qty_to_invoice to be computed as if the invoice_policy
    was set to "Ordered quantities", independently of the product configuration.

    This is needed for the automatic invoice logic, as we want to automatically
    invoice the full SO when it's paid.
    """
    for line in self.order_line:
        if line.state == "sale":
            # No need to set 0 as it is already the standard logic in the compute method.
            line.qty_to_invoice = line.product_uom_qty - line.qty_invoiced

def payment_action_capture(self):
    """Capture all transactions linked to this sale order."""
    self.ensure_one()
    payment_utils.check_rights_on_recordset(self)

    # In sudo mode to bypass the checks on the rights on the transactions.
    return self.sudo().transaction_ids.action_capture()

def get_portal_last_transaction(self):
    self.ensure_one()
    return self.sudo().transaction_ids._get_last()

def _get_order_lines_to_report(self):
    down_payment_lines = self.order_line.filtered(
        lambda line: (
            line.is_downpayment and not line.display_type and not line._get_downpayment_state()
        )
    )

    def show_line(line):
        if line.is_downpayment:
            return (
                # Only show the down payment section if down payments were posted
                (line.display_type and down_payment_lines)
                # Only show posted down payments
                or line in down_payment_lines
            )
        return line.display_type == "line_section" or not (
            line.parent_id.collapse_composition or line.parent_id.parent_id.collapse_composition
        )

    return self.order_line.filtered(show_line)

def create_document_from_attachment(self, attachment_ids):
    """Create the sale orders from given attachment_ids and redirect newly create order view.

    :param list attachment_ids: List of attachments process.
    :return: An action redirecting to related sale order view.
    :rtype: dict
    """
    attachments = self.env["ir.attachment"].browse(attachment_ids)
    if not attachments:
        raise UserError(self.env._("No attachment was provided"))

    orders = self.with_context(
        default_partner_id=self.env.user.partner_id.id
    )._create_records_from_attachments(attachments)

    return orders._get_records_action(name=self.env._("Generated Orders"))

def _has_to_be_paid(self):
    """Determine whether a sale order has to be paid.

    A sale order has to be paid when:
    - its state is 'draft' or 'sent';
    - it is not expired;
    - the prepayment percent is strictly positive;
    - the total amount is strictly positive.
    - confirmation amount is not reached

    Note: self.ensure_one()

    :return: Whether the sale order has to be paid.
    :rtype: bool
    """
    self.ensure_one()
    return (
        self.state in ["draft", "sent"]
        and not self.is_expired
        and self.prepayment_percent > 0
        and self.amount_total > 0
        and not self._is_confirmation_amount_reached()
    )

def _get_portal_return_action(self):
    """Return the action used to display orders when returning from customer portal."""
    self.ensure_one()
    return self.env.ref("sale.action_quotations_with_onboarding")

def _get_report_base_filename(self):
    self.ensure_one()
    return f"{self.type_name} {self.name}"

def get_empty_list_help(self, help_message):
    self = self.with_context(empty_list_help_document_name=self.env._("sale order"))
    return super().get_empty_list_help(help_message)

def _compute_field_value(self, field):
    if field.name != "invoice_status" or self.env.context.get("mail_activity_automation_skip"):
        return super()._compute_field_value(field)

    filtered_self = self.filtered(
        lambda so: (
            so.ids
            and (so.user_id or so.partner_id.user_id)
            and so._origin.invoice_status != "upselling"
        )
    )
    super()._compute_field_value(field)

    upselling_orders = filtered_self.filtered(lambda so: so.invoice_status == "upselling")
    upselling_orders._create_upsell_activity()

def _create_upsell_activity(self):
    if not self:
        return

    self.activity_unlink(["mail.mail_activity_data_todo"])
    for order in self:
        order_ref = order._get_html_link()
        customer_ref = order.partner_id._get_html_link()
        order.activity_schedule(
            "mail.mail_activity_data_todo",
            user_id=order.user_id.id or order.partner_id.user_id.id,
            note=order.env._(
                "Upsell %(order)s for customer %(customer)s",
                order=order_ref,
                customer=customer_ref,
            ),
        )

def _create_down_payment_lines_from_base_lines(self, down_payment_base_lines):
    """Add the base lines passed as parameter as sale order lines into the current sale order.

    :param down_payment_base_lines: A list of base lines
                                    (see '_prepare_base_line_for_taxes_computation').
    :return The newly created SO lines.
    """
    self.ensure_one()
    sequence = max(self.order_line.mapped("sequence") or [10]) + 1
    return (
        self
        .env["sale.order.line"]
        .with_context(sale_no_log_for_new_lines=True)
        .create([
            {
                **self._prepare_down_payment_line_values_from_base_line(base_line),
                "sequence": sequence + index,
            }
            for index, base_line in enumerate(down_payment_base_lines)
        ])
    )

def _prepare_down_payment_line_section_values(self):
    """Prepare the values to create a section line for the down payment on the current SO.

    :return: A dictionary to create a new SO section line.
    """
    self.ensure_one()
    return {"order_id": self.id, "display_type": "line_section", "is_downpayment": True}

def _get_prepayment_required_amount(self):
    """Return the default prepayment amount.

    :return: The default prepayment amount.
    :rtype: float
    """
    self.ensure_one()

    if self.prepayment_percent == 0:
        return 0
    return self.currency_id.round(self.amount_total * self.prepayment_percent)

def deliver_sold_quantity(self):
    invalid_targets = self.filtered(
        lambda o: (
            o.state != "sale"
            or any(line.qty_delivered_method != "manual" for line in o.order_line)
        )
    )
    if invalid_targets:
        raise UserError(
            self.env._(
                "The following sale orders %(invalid_orders)s can't be delivered. Cancelled all"
                " deliveries.",
                invalid_orders=", ".join(invalid_targets.mapped("name")),
            )
        )
    for order in self:
        for line in order.order_line:
            line.qty_delivered = line.product_uom_qty

def _get_or_create_analytic_account(self, plan_id):
    self.ensure_one()

    if not self.analytic_account_id:
        self.analytic_account_id = self.env["account.analytic.account"].create(
            self._prepare_analytic_account_data(plan_id=plan_id)
        )
    return self.analytic_account_id

def _get_action_add_from_catalog_extra_context(self):
    return {
        **super()._get_action_add_from_catalog_extra_context(),
        "order_customer_id": self.partner_id.id,
        "product_catalog_digits": self.order_line._fields["price_unit"].get_digits(self.env),
    }

def _get_product_catalog_default_prices(self, products, **kwargs) -> dict:
    # Override the default price computation to consider the pricelist prices instead.
    return self.pricelist_id._get_products_price(
        quantity=1.0,
        products=products,
        currency=self._get_catalog_currency(),
        date=self.date_order,
        **kwargs,
    )

def _get_product_catalog_product_data(self, product, **kwargs) -> dict:
    product_data = super()._get_product_catalog_product_data(product, **kwargs)
    has_warning_group = self.env["res.groups"]._is_feature_enabled("sale.group_warning_sale")
    if product.sale_line_warn_msg and has_warning_group:
        product_data.update(warning=product.sale_line_warn_msg)
    return product_data

def _get_product_documents(self):
    self.ensure_one()

    documents = (
        self.order_line.product_id.product_document_ids
        | self.order_line.product_template_id.product_document_ids
    )
    return self._filter_product_documents(documents).sorted()

def _filter_product_documents(self, documents):
    return documents.filtered(
        lambda document: (
            document.attached_on_sale == "quotation"
            or (self.state == "sale" and document.attached_on_sale == "sale_order")
        )
    )

def _is_partially_paid(self):
    """Return whether the sales order has a confirmed partial payment.

    The order is not considered "partially" paid if it's fully paid.

    :return: Whether the order is partially paid
    :rtype: bool
    """
    self.ensure_one()

    if self.state == "cancel":
        return False  # Allow resetting the cart when it's canceled from the backend

    if self._is_paid():
        return False

    return any(self.transaction_ids.filtered(lambda tx: tx.state in {"authorized", "done"}))

def _check_not_partially_paid(self):
    """Check if the order is partially paid, and raises an error if so.

    :rtype: None
    :raise UserError: If the error is partially paid
    """
    if self._is_partially_paid():
        raise UserError(
            self.env._(
                "It seems that there is already a payment in progress for your order; you can't"
                " modify it anymore."
            )
        )

def _get_lang(self):
    self.ensure_one()

    if self.partner_id.lang and not self.partner_id.is_public:
        return self.partner_id.lang

    return self.env.lang

def get_import_templates(self):
    return [
        {
            "label": self.env._("Template for Quotations"),
            "template": "/sale/static/xls/quotations_import_template.xlsx",
        }
    ]

def batch_onchange_sol(self, lines_data, order_changes, fields_spec):
    """Batch `sale.order.line` onchange calls into a single RPC.

    :param dict lines_data: {line_id: {"ids", "changes", "field_name"}}, one entry per line
    :param dict fields_spec: onchange fields spec, shared by every line
    :return: {line_id: recomputed values}
    :rtype: dict
    """
    SaleOrderLine = self.env["sale.order.line"]
    result = {}
    for line_id, data in lines_data.items():
        onchange_values = {**data["changes"], **order_changes}
        values = (
            SaleOrderLine
            .browse(data["ids"])
            .onchange(onchange_values, data["changed_fields"], fields_spec)
            .get("value", {})
        )
        result[line_id] = values
    return result

def _can_be_edited_on_portal(self):
    self.ensure_one()
    return self.state in ("draft", "sent")

def _get_period_domain(self, field, period_days, previous=False):  # noqa: PLR6301
    """Build a domain to filter records for a given time period.

    :param str field: The datetime field used for date filtering.
    :param int period_days: Number of days representing the target period.
    :param bool previous: When True, returns a domain for the previous equivalent period.
    :return: Domain used to filter records by date range.
    """
    if not previous:
        return Domain(field, ">", f"today -{period_days}d +1d")
    return Domain(field, ">", f"today -{period_days * 2}d +1d") & Domain(
        field, "<", f"today -{period_days}d +1d"
    )

def _get_invoiced(self):
    precision = self.env['decimal.precision'].precision_get('Product Unit')
    for order in self:
        if order.state != 'purchase':
            order.invoice_status = 'no'
            continue

        if any(
            not float_is_zero(line.qty_to_invoice, precision_digits=precision)
            for line in order.order_line.filtered(lambda l: not l.display_type)
        ):
            order.invoice_status = 'to invoice'
        elif (
            all(
                float_is_zero(line.qty_to_invoice, precision_digits=precision)
                for line in order.order_line.filtered(lambda l: not l.display_type)
            )
            and order.invoice_ids
        ):
            order.invoice_status = 'invoiced'
        else:
            order.invoice_status = 'no'

def _compute_invoice(self):
    for order in self:
        invoices = order.mapped('order_line.invoice_lines.move_id')
        order.invoice_ids = invoices
        order.invoice_count = len(invoices)

def _check_order_line_company_id(self):
    for order in self:
        invalid_companies = order.order_line.product_id.company_id.filtered(
            lambda c: order.company_id not in c._accessible_branches()
        )
        if invalid_companies:
            bad_products = order.order_line.product_id.filtered(
                lambda p: p.company_id and p.company_id in invalid_companies
            )
            raise ValidationError(_(
                "Your RFQ contains products from company %(product_company)s whereas your RFQ belongs to company %(quote_company)s. \n Please change the company of your RFQ or remove the products from other companies (%(bad_products)s).",
                product_company=', '.join(invalid_companies.sudo().mapped('display_name')),
                quote_company=order.company_id.display_name,
                bad_products=', '.join(bad_products.mapped('display_name')),
            ))

def _compute_access_url(self):
    super(PurchaseOrder, self)._compute_access_url()
    for order in self:
        order.access_url = '/my/purchase/%s' % (order.id)

def _compute_bill_matched_ratio(self):
    def get_line_invoiced_ratio(line):
        base_quantity = line.product_qty if line.product_id.purchase_method == 'purchase' else line.qty_received
        return line.qty_invoiced / base_quantity if base_quantity else 0

    for order in self:
        product_lines = order.order_line.filtered(lambda pol: not pol.display_type)
        invoiced_ratio = [get_line_invoiced_ratio(line) for line in product_lines]
        order.bill_matched_ratio = sum(invoiced_ratio) / len(product_lines) * 100 if product_lines else 0

def _compute_date_calendar_start(self):
    for order in self:
        order.date_calendar_start = order.date_approve if (order.state == 'purchase') else order.date_order

def _compute_currency_rate(self):
    for order in self:
        order.currency_rate = self.env['res.currency']._get_conversion_rate(
            from_currency=order.company_id.currency_id,
            to_currency=order.currency_id,
            company=order.company_id,
            date=(order.date_order or fields.Datetime.now()).date(),
        )

def _compute_amount_total_cc(self):
    for order in self:
        order.amount_total_cc = order.amount_total / order.currency_rate

def _compute_date_planned(self):
    """ date_planned = the earliest date_planned across all order lines. """
    for order in self:
        dates_list = order.order_line.filtered(lambda x: not x.display_type and x.date_planned).mapped('date_planned')
        if dates_list:
            order.date_planned = min(dates_list)
        else:
            order.date_planned = False

def _compute_display_name(self):
    for po in self:
        name = po.name
        if po.partner_ref:
            name += ' (' + po.partner_ref + ')'
        if self.env.context.get('show_total_amount') and po.amount_total:
            name += ': ' + formatLang(self.env, po.amount_total, currency_obj=po.currency_id)
        po.display_name = name

def _compute_receipt_status(self):
    for order in self:
        if order.state != 'purchase' or not order.order_line:
            order.receipt_status = False
        elif all(line.qty_received >= line.product_qty for line in order.order_line):
            order.receipt_status = 'full'
        elif any(line.qty_received for line in order.order_line):
            order.receipt_status = 'partial'
        else:
            order.receipt_status = 'pending'

def _compute_receipt_reminder_email(self):
    for order in self:
        order.receipt_reminder_email = order.partner_id.with_company(order.company_id).receipt_reminder_email
        order.reminder_date_before_receipt = order.partner_id.with_company(order.company_id).reminder_date_before_receipt

def _compute_tax_country_id(self):
    for record in self:
        if record.fiscal_position_id.foreign_vat:
            record.tax_country_id = record.fiscal_position_id.country_id
        else:
            record.tax_country_id = record.company_id.account_fiscal_country_id

def _compute_incoterm_id(self):
    for po in self:
        partner_incoterm = po.partner_id.purchase_incoterm_id
        if partner_incoterm:
            po.incoterm_id = partner_incoterm

def _compute_incoterm_location(self):
    for po in self:
        partner_incoterm_location = po.partner_id.purchase_incoterm_location
        if partner_incoterm_location:
            po.incoterm_location = partner_incoterm_location

def _compute_show_comparison(self):
    line_groupby_product = self.env['purchase.order.line']._read_group(
        [('product_id', 'in', self.order_line.product_id.ids), ('state', '=', 'purchase')],
        ['product_id'],
        ['order_id:array_agg']
    )

    order_by_product = {p: set(o_ids) for p, o_ids in line_groupby_product}
    for record in self:
        record.show_comparison = any(set(record.ids) != order_by_product[p] for p in record.order_line.product_id if p in order_by_product)

def _compute_show_receive_button(self):
    for order in self:
        order.show_receive_button = (
            order.state == 'purchase'
            and any(line.qty_received < line.product_qty for line in order.order_line)
            and all(line.qty_received_method == "manual" for line in order.order_line)
        )

def _compute_purchase_warning_text(self):
    if not self.env.user.has_group('purchase.group_warning_purchase'):
        self.purchase_warning_text = ''
        return
    for order in self:
        warnings = OrderedSet()
        if partner_msg := order.partner_id.purchase_warn_msg:
            warnings.add((order.partner_id.name or order.partner_id.display_name) + ' - ' + partner_msg)
        if partner_parent_msg := order.partner_id.parent_id.purchase_warn_msg:
            parent = order.partner_id.parent_id
            warnings.add((parent.name or parent.display_name) + ' - ' + partner_parent_msg)
        for line in order.order_line:
            if product_msg := line.purchase_line_warn_msg:
                warnings.add(line.product_id.display_name + ' - ' + product_msg)
        order.purchase_warning_text = '\n'.join(warnings)

def action_open_business_doc(self):
    self.ensure_one()
    return {
        'name': _("Order"),
        'type': 'ir.actions.act_window',
        'res_model': 'purchase.order',
        'res_id': self.id,
        'views': [(False, 'form')],
    }

def onchange_date_planned(self):
    if self.date_planned:
        self.order_line.filtered(lambda line: not line.display_type).date_planned = self.date_planned

def _search_is_late(self, operator, value):
    if operator not in ["=", "!="]:
        raise ValidationError(self.env._("Unsupported operator"))
    purchase_domain = self._get_domain_is_late(operator, value)
    if operator == "=" and value or operator == "!=" and not value:
        purchase_lines_late = Domain('order_id', 'any', purchase_domain) & Domain.custom(
            to_sql=lambda table: SQL("%s < %s", table.qty_received, table.product_qty),
        )
        return Domain('order_line', 'any', purchase_lines_late)
    else:
        purchase_lines_on_time = Domain('order_id', 'any', purchase_domain) & Domain.custom(
            to_sql=lambda table: SQL("%s >= %s", table.qty_received, table.product_qty),
        )
        return Domain('order_line', 'any', purchase_lines_on_time)

def create(self, vals_list):
    orders = self.browse()
    for vals in vals_list:
        company_id = vals.get('company_id', self.default_get(['company_id'])['company_id'])
        # Ensures default picking type and currency are taken from the right company.
        self_comp = self.with_company(company_id)
        if vals.get('name', _('New')) == _('New'):
            seq_date = None
            if 'date_order' in vals:
                seq_date = fields.Datetime.context_timestamp(self, fields.Datetime.to_datetime(vals['date_order']))
            vals['name'] = self_comp.env['ir.sequence'].next_by_code('purchase.order', sequence_date=seq_date) or '/'
        orders |= super(PurchaseOrder, self_comp).create(vals)
    return orders

def _unlink_if_cancelled(self):
    for order in self:
        if not order.state == 'cancel':
            raise UserError(_('In order to delete a purchase order, you must cancel it first.'))

def copy(self, default=None):
    ctx = dict(self.env.context)
    ctx.pop('default_product_id', None)
    self = self.with_context(ctx)
    new_pos = super().copy(default=default)
    for line in new_pos.order_line:
        if line.product_id:
            line.date_planned = line._get_date_planned(line._get_seller_info())
    return new_pos

def _must_delete_date_planned(self, field_name):
    # To be overridden
    return field_name == 'order_line'

def onchange(self, values, field_names, fields_spec):
    """
    Override onchange to NOT update all date_planned on PO lines when
    date_planned on PO is updated by the change of date_planned on PO lines.
    """
    result = super().onchange(values, field_names, fields_spec)
    if any(self._must_delete_date_planned(field) for field in field_names) and 'value' in result:
        for line in result['value'].get('order_line', []):
            if line[0] == Command.UPDATE and 'date_planned' in line[2]:
                del line[2]['date_planned']
    return result

def _get_report_base_filename(self):
    self.ensure_one()
    return 'Purchase Order-%s' % (self.name)

def onchange_partner_id(self):
    # Ensures all properties and fiscal positions
    # are taken with the company of the order
    # if not defined, with_company doesn't change anything.
    self = self.with_company(self.company_id)
    if not self.partner_id:
        self.fiscal_position_id = False
    else:
        self.fiscal_position_id = self.env['account.fiscal.position']._get_fiscal_position(self.partner_id)
        self.payment_term_id = self.partner_id.property_supplier_payment_term_id.id
        if self.partner_id.buyer_id:
            self.user_id = self.partner_id.buyer_id
    return {}

def _compute_currency_id(self):
    for order in self:
        order = order.with_company(order.company_id)
        if not order.partner_id:
            order.currency_id = order.company_id.currency_id
        else:
            order.currency_id = order.partner_id.property_purchase_currency_id or order.company_id.currency_id

def _compute_document_tax_mode(self):
    for order in self:
        if not order.document_tax_mode:
            company = order.company_id or self.env.company
            order.document_tax_mode = company.account_price_include

def message_post(self, **kwargs):
    if self.env.context.get('mark_rfq_as_sent'):
        self._mark_rfqs_as_sent()
        kwargs['notify_author_mention'] = kwargs.get('notify_author_mention', True)
    return super().message_post(**kwargs)

def _message_mail_after_hook(self, mails):
    self._mark_rfqs_as_sent()
    return super()._message_mail_after_hook(mails)

def _notify_get_recipients_groups(self, message, model_description):
    # Tweak 'view document' button for portal customers, calling directly routes for confirm specific to PO model.
    groups = super()._notify_get_recipients_groups(message, model_description)
    if not self:
        return groups

    self.ensure_one()
    try:
        customer_portal_group = next(group for group in groups if group[0] == 'portal_customer')
    except StopIteration:
        pass
    else:
        access_opt = customer_portal_group[2].setdefault('button_access', {})
        if self.env.context.get('is_reminder'):
            access_opt['title'] = _('View')
        else:
            access_opt.update(
                title=_("View Quotation") if self.state in ('draft', 'sent') else _("View Order"),
                url=self.get_base_url() + self.get_confirm_url(),
            )

    return groups

def _track_log_get_default_subtype(self, track_init_values):
    self.ensure_one()
    if 'state' in track_init_values and self.state == 'purchase':
        if track_init_values['state'] == 'to approve':
            return self.env.ref('purchase.mt_rfq_approved')
        return self.env.ref('purchase.mt_rfq_confirmed')
    elif 'state' in track_init_values and self.state == 'to approve':
        return self.env.ref('purchase.mt_rfq_confirmed')
    elif 'state' in track_init_values and self.state == 'sent':
        return self.env.ref('purchase.mt_rfq_sent')
    return super()._track_log_get_default_subtype(track_init_values)

def action_receive(self):
    invalid_targets = self.filtered(
        lambda o: o.state != "purchase" or
        any(line.qty_received_method != "manual" for line in o.order_line)
    )
    if invalid_targets:
        raise UserError(
            _("The following purchase orders %(invalid_orders)s can't be received. Cancelled all receptions.",
            invalid_orders=invalid_targets))
    for order in self:
        for line in order.order_line:
            line.qty_received = line.product_qty

def button_approve(self, force=False):
    self = self.filtered(lambda order: order._approval_allowed())
    self.write({'state': 'purchase', 'date_approve': fields.Datetime.now()})
    self.filtered(lambda p: p.lock_confirmed_po == 'lock').write({'locked': True})
    return {}

def button_draft(self):
    self.write({'state': 'draft'})
    return {}

def button_confirm(self):
    for order in self:
        if order.state not in ['draft', 'sent']:
            continue
        error_msg = order._confirmation_error_message()
        if error_msg:
            raise UserError(error_msg)
        order.order_line._validate_analytic_distribution()
        # Deal with double validation process
        if order._approval_allowed():
            order.button_approve()
        else:
            order.write({'state': 'to approve'})
    return True

def button_cancel(self):
    locked_purchase_orders = self.filtered(lambda po: po.locked)
    if locked_purchase_orders:
        raise UserError(self.env._("Unable to cancel purchase order(s): %s. You must first unlock them.", locked_purchase_orders.mapped('display_name')))

    purchase_orders_with_invoices = self.filtered(lambda po: any(i.state not in ('cancel', 'draft') for i in po.invoice_ids))
    if purchase_orders_with_invoices:
        raise UserError(_("Unable to cancel purchase order(s): %s. You must first cancel their related vendor bills.", purchase_orders_with_invoices.mapped('display_name')))
    self.write({'state': 'cancel'})

def button_reset_date_order(self):
    self.ensure_one()
    previous_date_order = self.date_order
    self.date_order = fields.Datetime.now()
    for line in self.order_line:
        # If there's no seller i.e no lead time, we keep the same difference with the new deadline
        if not line.selected_seller_id and line.date_planned:
            diff = line.date_planned - previous_date_order
            line.date_planned = self.date_order + diff if diff.days >= 0 else self.date_order
        else:
            line.date_planned = line._get_date_planned(line.selected_seller_id._get_seller_info())

def _confirmation_error_message(self):
    """ Return whether order can be confirmed or not if not then return error message. """
    self.ensure_one()
    if any(
        not line.display_type
        and not line.is_downpayment
        and not line.product_id
        for line in self.order_line
    ):
        return _("Some order lines are missing a product, you need to correct them before going further.")

    return False

def action_bill_matching(self):
    self.ensure_one()
    return {
        'type': 'ir.actions.act_window',
        'name': _("Bill Matching"),
        'res_model': 'purchase.bill.line.match',
        'context': {
            'partner_id': self.partner_id.id,
        },
        'domain': [
            ('partner_id', 'in', (self.partner_id | self.partner_id.commercial_partner_id).ids),
            ('company_id', 'in', self.env.company.ids),
            '|', '|',
            ('purchase_order_id', '=', self.id),
            ('matching_id', '=', 0),
            ('aml_id.purchase_order_id', '=', self.id),
        ],
        'views': [(self.env.ref('purchase.purchase_bill_line_match_tree').id, 'list')],
    }

def _prepare_down_payment_section_values(self):
    self.ensure_one()
    context = {'lang': self.partner_id.lang}
    res = {
        'product_qty': 0.0,
        'order_id': self.id,
        'display_type': 'line_section',
        'is_downpayment': True,
        'sequence': (self.order_line[-1:].sequence or 9) + 1,
        'name': _("Down Payments"),
    }
    del context
    return res

def _create_downpayments(self, line_vals):
    self.ensure_one()

    # create section
    if not any(line.display_type and line.is_downpayment for line in self.order_line):
        section_line = self.order_line.create(self._prepare_down_payment_section_values())
    else:
        section_line = self.order_line.filtered(lambda line: line.display_type and line.is_downpayment)
    vals = [
        {
            **line_val,
            'sequence': section_line.sequence + i,
        }
        for i, line_val in enumerate(line_vals, start=1)
    ]
    downpayment_lines = self.env['purchase.order.line'].create(vals)
    self.order_line = [
        Command.link(line_id)
        for line_id in downpayment_lines.ids
    ]  # a simple concatenation would cause all order_line to recompute, we do not want it to happen
    return downpayment_lines

def action_view_invoice(self, invoices=False):
    """This function returns an action that display existing vendor bills of
    given purchase order ids. When only one found, show the vendor bill
    immediately.
    """
    if not invoices:
        self.invalidate_model(['invoice_ids'])
        invoices = self.invoice_ids

    result = self.env['ir.actions.act_window']._for_xml_id('account.action_move_in_invoice_type')
    # choose the view_mode accordingly
    if len(invoices) > 1:
        result['domain'] = [('id', 'in', invoices.ids)]
    elif len(invoices) == 1:
        res = self.env.ref('account.view_move_form', False)
        form_view = [(res and res.id or False, 'form')]
        if 'views' in result:
            result['views'] = form_view + [(state, view) for state, view in result['views'] if view != 'form']
        else:
            result['views'] = form_view
        result['res_id'] = invoices.id
    else:
        result = {'type': 'ir.actions.act_window_close'}

    result['context'] = literal_eval(result['context'])
    if len(self.partner_id) == 1:
        result['context']['default_partner_id'] = self.partner_id.id
    return result

def _send_reminder_mail(self, send_single=False):
    if not self.env.user.has_group('purchase.group_send_reminder'):
        return

    template = self.env.ref('purchase.email_template_edi_purchase_reminder', raise_if_not_found=False)
    if template:
        orders = self if send_single else self._get_orders_to_remind()
        for order in orders:
            date = order.date_planned
            if date and (send_single or (date - relativedelta(days=order.reminder_date_before_receipt)).date() == datetime.today().date()):
                if send_single:
                    return order._send_reminder_open_composer(template.id)
                else:
                    order.with_context(is_reminder=True).message_post_with_source(
                        template,
                        email_layout_xmlid="mail.mail_notification_layout_with_responsible_signature",
                        subtype_xmlid='mail.mt_comment',
                    )

def send_reminder_preview(self):
    self.ensure_one()
    if not self.env.user.has_group('purchase.group_send_reminder'):
        return

    template = self.env.ref('purchase.email_template_edi_purchase_reminder', raise_if_not_found=False)
    if template and self.env.user.email and self.id:
        template.with_context(is_reminder=True).send_mail(
            self.id,
            force_send=True,
            raise_exception=False,
            email_layout_xmlid="mail.mail_notification_layout_with_responsible_signature",
            email_values={'email_to': self.env.user.email, 'recipient_ids': []},
        )
        return {'toast_message': _("A sample email has been sent to %s.", self.env.user.email)}

def _get_action_add_from_catalog_extra_context(self):
    return {
        **super()._get_action_add_from_catalog_extra_context(),
        'precision': self.env['decimal.precision'].precision_get('Product Unit'),
        'product_catalog_digits': self.order_line._fields['price_unit'].get_digits(self.env),
        'is_purchase_document': True,
        'search_default_sold_by_vendor_id': self.partner_id.id,
        'partner_id': self.partner_id.id,
    }

def _get_product_catalog_product_data(self, product, **kwargs) -> dict:
    return {
        **super()._get_product_catalog_product_data(product, **kwargs),
        **self._get_product_catalog_seller_data(product, **kwargs),
    }

def _get_product_catalog_default_unit_price(self, product, uom, **kwargs) -> float:
    seller_data = self._get_product_catalog_seller_data(product, uom=uom, **kwargs)
    return seller_data.get('price') or super()._get_product_catalog_default_unit_price(
        product, uom, **kwargs
    )

def get_confirm_url(self, confirm_type=None):
    """Create url for confirm reminder or purchase reception email for sending
    in mail. Unsuported anymore. We only use the acknowledge mechanism. Keep it
    for backward compatibility"""
    if confirm_type in ['reminder', 'reception', 'decline']:
        return self.get_acknowledge_url()
    return self.get_portal_url()

def get_update_url(self):
    """Create portal url for user to update the scheduled date on purchase
    order lines."""
    update_param = url_encode({'update': 'True'})
    return self.get_portal_url(query_string='&%s' % update_param)

def get_localized_date_planned(self, date_planned=False):
    """Returns the localized date planned in the timezone of the order's user or the
    company's partner or UTC if none of them are set."""
    self.ensure_one()
    date_planned = date_planned or self.date_planned
    if not date_planned:
        return False
    if isinstance(date_planned, str):
        date_planned = fields.Datetime.from_string(date_planned)
    tz = self.get_order_timezone()
    return date_planned.astimezone(tz)

def get_order_timezone(self):
    """ Returns the timezone of the order's user or the company's partner
    or UTC if none of them are set. """
    self.ensure_one()
    return ZoneInfo(self.user_id.tz or self.company_id.partner_id.tz or 'UTC')

def _update_update_date_activity(self, updated_dates, activity):
    for line, date in updated_dates:
        activity.note += Markup('<p> - %s</p>\n') %  _(
            '%(product)s from %(original_receipt_date)s to %(new_receipt_date)s',
            product=line.product_id.display_name,
            original_receipt_date=line.date_planned.date(),
            new_receipt_date=date.date()
        )

def get_import_templates(self):
    return [{
        'label': _('Template for Requests for Quotation'),
        'template': '/purchase/static/xls/requests_for_quotation_import_template.xlsx',
    }]

def _default_picking_type_id(self):
    picking_type_code = self.env.context.get('restricted_picking_type_code')
    if picking_type_code:
        picking_types = self.env['stock.picking.type'].search([
            ('code', '=', picking_type_code),
            ('company_id', '=', self.env.company.id),
        ])
        return picking_types[:1].id

def _compute_display_name(self):
    super()._compute_display_name()
    if self.env.context.get('formatted_display_name'):
        for picking in self:
            extra_display_info = []
            if picking.origin:
                extra_display_info.append(picking.origin)
            if picking.partner_id:
                extra_display_info.append(picking.partner_id.display_name)
            if extra_display_info:
                picking.display_name += f'\t--{" ".join(extra_display_info)}--'
    elif self.env.context.get('display_name_partner'):
        for picking in self:
            if not picking.partner_id:
                continue
            picking.display_name = f"{picking.display_name} - {picking.partner_id.display_name}"

def _compute_has_tracking(self):
    for picking in self:
        picking.has_tracking = any(m.product_id.tracking in ['lot', 'serial'] for m in picking.move_ids)

def _compute_move_type(self):
    for record in self:
        record.move_type = record.picking_type_id.move_type

def _compute_has_deadline_issue(self):
    for picking in self:
        picking.has_deadline_issue = picking.date_deadline and picking.date_deadline < picking.scheduled_date or False

def _search_date_category(self, operator, value):
    if operator != 'in':
        return NotImplemented
    return Domain.OR(
        self.date_category_to_domain('scheduled_date', item)
        for item in value
    )

def _compute_delay_alert_date(self):
    delay_alert_date_data = self.env['stock.move']._read_group([('id', 'in', self.move_ids.ids), ('delay_alert_date', '!=', False)], ['picking_id'], ['delay_alert_date:max'])
    delay_alert_date_data = {picking.id: delay_alert_date for picking, delay_alert_date in delay_alert_date_data}
    for picking in self:
        picking.delay_alert_date = delay_alert_date_data.get(picking.id, False)

def _compute_is_signed(self):
    for picking in self:
        picking.is_signed = picking.signature

def _compute_is_date_editable(self):
    for picking in self:
        if picking.state in ['done', 'cancel']:
            picking.is_date_editable = not picking.is_locked
        else:
            picking.is_date_editable = True

def _compute_show_lots_text(self):
    group_production_lot_enabled = self.env.user.has_group('stock.group_production_lot')
    for picking in self:
        if not picking.move_line_ids and not picking.picking_type_id.use_create_lots:
            picking.show_lots_text = False
        elif group_production_lot_enabled and picking.picking_type_id.use_create_lots \
                and not picking.picking_type_id.use_existing_lots and picking.state != 'done':
            picking.show_lots_text = True
        else:
            picking.show_lots_text = False

def _compute_json_popover(self):
    picking_no_alert = self.filtered(lambda p: p.state in ('done', 'cancel') or not p.delay_alert_date)
    picking_no_alert.json_popover = False
    for picking in (self - picking_no_alert):
        picking.json_popover = json.dumps({
            'popoverTemplate': 'stock.PopoverStockRescheduling',
            'delay_alert_date': format_datetime(self.env, picking.delay_alert_date, dt_format=False),
            'late_elements': [{
                'id': late_move.id,
                'name': late_move.sudo().display_name,  # sudo need for cross company transfers
                'model': late_move._name,
            } for late_move in picking.move_ids.filtered(lambda m: m.delay_alert_date).move_orig_ids._delay_alert_get_documents()
            ]
        })

def _compute_state(self):
    ''' State of a picking depends on the state of its related stock.move
    - Draft: only used for "planned pickings"
    - Waiting: if the picking is not ready to be sent so if
      - (a) no quantity could be reserved at all or if
      - (b) some quantities could be reserved and the shipping policy is "deliver all at once"
    - Waiting another move: if the picking is waiting for another move
    - Ready: if the picking is ready to be sent so if:
      - (a) all quantities are reserved or if
      - (b) some quantities could be reserved and the shipping policy is "as soon as possible"
      - (c) it's an incoming picking
    - Done: if the picking is done.
    - Cancelled: if the picking is cancelled
    '''
    picking_moves_state_map = defaultdict(dict)
    picking_move_lines = defaultdict(set)
    for move in self.env['stock.move'].search([('picking_id', 'in', self.ids)]):
        picking_id = move.picking_id
        move_state = move.state
        picking_moves_state_map[picking_id.id].update({
            'any_draft': picking_moves_state_map[picking_id.id].get('any_draft', False) or move_state == 'draft',
            'all_cancel': picking_moves_state_map[picking_id.id].get('all_cancel', True) and move_state == 'cancel',
            'all_cancel_done': picking_moves_state_map[picking_id.id].get('all_cancel_done', True) and move_state in ('cancel', 'done'),
            'all_done_are_scrapped': picking_moves_state_map[picking_id.id].get('all_done_are_scrapped', True) and (move.is_scrap if move_state == 'done' else True),
            'any_cancel_and_not_scrapped': picking_moves_state_map[picking_id.id].get('any_cancel_and_not_scrapped', False) or (move_state == 'cancel' and not move.is_scrap),
        })
        picking_move_lines[picking_id.id].add(move.id)
    for picking in self:
        picking_id = (picking.ids and picking.ids[0]) or picking.id
        if not picking_moves_state_map[picking_id] or picking_moves_state_map[picking_id]['any_draft']:
            picking.state = 'draft'
        elif picking_moves_state_map[picking_id]['all_cancel']:
            picking.state = 'cancel'
        elif picking_moves_state_map[picking_id]['all_cancel_done']:
            if picking_moves_state_map[picking_id]['all_done_are_scrapped'] and picking_moves_state_map[picking_id]['any_cancel_and_not_scrapped']:
                picking.state = 'cancel'
            else:
                picking.state = 'done'
        else:
            if picking.location_id.should_bypass_reservation() and all(m.procure_method == 'make_to_stock' for m in picking.move_ids):
                picking.state = 'assigned'
            else:
                relevant_move_state = self.env['stock.move'].browse(picking_move_lines[picking_id])._get_relevant_state_among_moves()
                if relevant_move_state == 'partially_available':
                    picking.state = 'assigned'
                else:
                    picking.state = relevant_move_state

def _compute_scheduled_date(self):
    for picking in self:
        if not picking.id:
            continue
        moves_dates = picking.move_ids.filtered(lambda move: move.state not in ('done', 'cancel')).mapped('date')
        if picking.move_type == 'direct':
            picking.scheduled_date = min(moves_dates, default=picking.scheduled_date or fields.Datetime.now())
        else:
            picking.scheduled_date = max(moves_dates, default=picking.scheduled_date or fields.Datetime.now())

def _compute_bulk_weight(self):
    picking_weights = defaultdict(float)
    res_groups = self.env['stock.move.line']._read_group(
        [('picking_id', 'in', self.ids), ('product_id', '!=', False), ('result_package_id', '=', False)],
        ['picking_id', 'product_id', 'uom_id', 'quantity'],
        ['__count'],
    )
    for picking, product, uom_id, quantity, count in res_groups:
        picking_weights[picking.id] += (
            count
            * uom_id._compute_quantity(quantity, product.uom_id)
            * product.weight
        )
    for picking in self:
        picking.weight_bulk = picking_weights[picking.id]

def _compute_shipping_weight(self):
    all_packages = self.move_line_ids.result_package_id.outermost_package_id.sudo()
    if all_packages:
        # Batched over all pickings in self instead of one _get_weight() call per picking,
        # which turned this compute into an N+1 (2 extra queries per picking).
        children_by_dest_pack, all_pack_ids = all_packages._get_all_children_package_dest_ids()
        base_weight_per_package = {p.id: p.package_type_id.base_weight for p in self.env['stock.package'].sudo().browse(all_pack_ids)}
        move_line_groups = self.env['stock.move.line'].sudo()._read_group(
            [('result_package_id', 'in', all_pack_ids), ('product_id', '!=', False), ('picking_id', 'in', self.ids)],
            ['picking_id', 'result_package_id', 'product_id', 'uom_id', 'quantity'],
            ['__count'],
        )
        product_weight_by_picking_package = defaultdict(float)
        for picking_g, result_package, product, product_uom, quantity, count in move_line_groups:
            product_weight_by_picking_package[picking_g.id, result_package.id] += (
                count
                * product_uom._compute_quantity(quantity, product.uom_id)
                * product.weight
            )

    for picking in self:
        # if shipping weight is not assigned => default to calculated product weight
        shipping_weight = picking.weight_bulk
        relevant_packages = picking.move_line_ids.result_package_id.outermost_package_id
        for package in relevant_packages:
            if package.shipping_weight:
                shipping_weight += package.shipping_weight
                continue
            weight = base_weight_per_package.get(package.id, 0) + product_weight_by_picking_package.get((picking.id, package.id), 0)
            for child_id in children_by_dest_pack.get(package, []):
                weight += base_weight_per_package.get(child_id, 0) + product_weight_by_picking_package.get((picking.id, child_id), 0)
            shipping_weight += weight
        picking.shipping_weight = shipping_weight

def _compute_shipping_volume(self):
    for picking in self:
        volume = 0
        for move in picking.move_ids:
            volume += move.uom_id._compute_quantity(move.quantity, move.product_id.uom_id) * move.product_id.volume
        picking.shipping_volume = volume

def _compute_date_deadline(self):
    for picking in self:
        moves = picking.move_ids.filtered(lambda m: m.state != 'cancel' and m.date_deadline)
        if picking.move_type == 'direct':
            picking.date_deadline = min(moves.mapped('date_deadline'), default=False)
        else:
            picking.date_deadline = max(moves.mapped('date_deadline'), default=False)

def _set_scheduled_date(self):
    for picking in self:
        if picking.state == 'cancel':
            raise UserError(_("You cannot change the Scheduled Date on a cancelled transfer."))
        if picking.state == 'done':
            continue
        picking.move_ids.write({'date': picking.scheduled_date})

def _has_scrap_move(self):
    result = {
        picking
        for [picking] in self.env['stock.move']._read_group(
            [('picking_id', 'in', self.ids), ('is_scrap', '=', True)],
            ['picking_id'],
        )
    }
    for picking in self:
        picking.has_scrap_move = picking._origin in result

def _compute_packages_count(self):
    done_pickings = self.filtered(lambda picking: picking.state == 'done')
    other_pickings = self - done_pickings

    packages_by_pick = defaultdict(int)
    # Cannot _read_group() as picking_ids isn't stored, nor grouped() because multiple pickings per package
    packages = self.env['stock.package'].search([('picking_ids', 'in', other_pickings.ids)])
    for pack in packages:
        for picking in pack.picking_ids:
            packages_by_pick[picking] += 1

    histories_by_pick = self.env['stock.package.history']._read_group([
        ('picking_ids', 'in', done_pickings.ids)], ['picking_ids'], ['__count'])
    histories_by_pick = dict(histories_by_pick)

    for picking in done_pickings:
        picking.packages_count = histories_by_pick.get(picking, 0)
    for picking in other_pickings:
        picking.packages_count = packages_by_pick.get(picking, 0)

def _compute_show_check_availability(self):
    """ According to `picking.show_check_availability`, the "Reserve" button will be
    displayed in the form view of a picking.
    """
    for picking in self:
        if picking.state not in ('confirmed', 'waiting', 'assigned'):
            picking.show_check_availability = False
            continue
        if all(m.picked or m.product_uom_qty == m.quantity for m in picking.move_ids):
            picking.show_check_availability = False
            continue
        picking.show_check_availability = any(
            move.state in ('waiting', 'confirmed', 'partially_available') and
            move.uom_id.compare(move.product_uom_qty, 0)
            for move in picking.move_ids
        )

def _compute_show_allocation(self):
    self.show_allocation = False
    for picking in self:
        if picking.picking_type_id.auto_show_allocation_report:
            picking.show_allocation = picking._get_show_allocation(picking.picking_type_id)

def _compute_location_id(self):
    default_supplier_location_id = self.env['ir.default'].sudo()._get('res.partner', 'property_stock_supplier')
    for picking in self:
        if picking.state in ('cancel', 'done') or picking.return_id:
            continue
        picking = picking.with_company(picking.company_id)
        if picking.picking_type_id:
            location_src = picking.picking_type_id.default_location_src_id
            if location_src.usage == 'supplier' and picking.partner_id:
                supplier_location = picking.partner_id.property_stock_supplier
                if supplier_location and supplier_location.id != default_supplier_location_id:
                    location_src = supplier_location
            picking.location_id = location_src.id

def _compute_location_dest_id(self):
    default_customer_location_id = self.env['ir.default'].sudo()._get('res.partner', 'property_stock_customer')
    for picking in self:
        if picking.state in ('cancel', 'done') or picking.return_id:
            continue
        picking = picking.with_company(picking.company_id)
        if picking.picking_type_id:
            location_dest = picking.picking_type_id.default_location_dest_id
            if location_dest.usage == 'customer' and picking.partner_id:
                customer_location = picking.partner_id.property_stock_customer
                if customer_location and customer_location.id != default_customer_location_id:
                    location_dest = customer_location
            picking.location_dest_id = location_dest.id

def _compute_return_count(self):
    for picking in self:
        picking.return_count = len(picking.return_ids)

def _compute_picking_warning_text(self):
    if not self.env.user.has_group('stock.group_warning_stock'):
        self.picking_warning_text = ''
        return
    for picking in self:
        text = ''
        if partner_msg := picking.partner_id.picking_warn_msg:
            text += partner_msg + '\n'
        if parent_msg := picking.partner_id.parent_id.picking_warn_msg:
            text += parent_msg + '\n'
        picking.picking_warning_text = text

def _get_next_transfers(self):
    next_pickings = self.move_ids.move_dest_ids.picking_id
    return next_pickings.filtered(lambda p: p not in self.return_ids)

def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def _search_products_availability_state(self, operator, value):
    if operator != 'in':
        return NotImplemented

    invalid_states = ('done', 'cancel', 'draft')
    if False in value:
        return ['|', ('state', 'in', invalid_states), *self._search_products_availability_state('in', value - {False})]
    value = set(self._fields['products_availability_state'].get_values(self.env)) & value
    if not value:
        return Domain.FALSE

    def _get_comparison_date(move):
        return move.picking_id.scheduled_date

    def _filter_picking_moves(picking):
        try:
            return picking.move_ids._match_searched_availability(operator, value, _get_comparison_date)
        except UserError:
            # invalid value for search
            return False

    pickings = self.env['stock.picking'].search([('state', 'not in', invalid_states)], order='id').filtered(_filter_picking_moves)
    return Domain('id', 'in', pickings.ids)

def get_empty_list_help(self, help_message):
    return self.env['ir.ui.view']._render_template(
        'stock.help_message_template', {
            'picking_type_code': self.env.context.get('restricted_picking_type_code') or self.picking_type_code,
        }
    )

def _search_delay_alert_date(self, operator, value):
    if operator in Domain.NEGATIVE_OPERATORS:
        return NotImplemented
    return [('move_ids.delay_alert_date', operator, value)]

def _onchange_picking_type(self):
    if self.picking_type_id and self.state == 'draft':
        self = self.with_company(self.company_id)
        self.move_ids.filtered(
            lambda m: m.picking_type_id != self.picking_type_id
        ).picking_type_id = self.picking_type_id
        self.move_ids.company_id = self.company_id

def _onchange_location_id(self):
    self.move_ids.location_id = self.location_id
    for move in self.move_ids.filtered(lambda m: m.move_orig_ids):
        for ml in move.move_line_ids:
            parent_path = [int(loc_id) for loc_id in ml.location_id.parent_path.split('/')[:-1]]
            if self.location_id.id not in parent_path:
                return {'warning': {
                        'title': _("Warning: change source location"),
                        'message': _("Updating the location of this transfer will result in unreservation of the currently assigned items. "
                                     "An attempt to reserve items at the new location will be made and the link with preceding transfers will be discarded.\n\n"
                                     "To avoid this, please discard the source location change before saving.")
                    }
                }

def create(self, vals_list):
    scheduled_dates = []
    for vals in vals_list:
        defaults = self.default_get(['name', 'picking_type_id'])
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id', defaults.get('picking_type_id')))
        if vals.get('name', '/') == '/' and defaults.get('name', '/') == '/' and vals.get('picking_type_id', defaults.get('picking_type_id')):
            if picking_type.sequence_id:
                vals['name'] = picking_type.sequence_id.next_by_id()

        # make sure to write `schedule_date` *after* the `stock.move` creation in
        # order to get a determinist execution of `_set_scheduled_date`
        scheduled_dates.append(vals.pop('scheduled_date', False))

    pickings = super().create(vals_list)

    for picking, scheduled_date in zip(pickings, scheduled_dates):
        if scheduled_date:
            picking.with_context(mail_notrack=True).write({'scheduled_date': scheduled_date})
    pickings._autoconfirm_picking()

    for picking, vals in zip(pickings, vals_list):
        if vals.get('batch_id'):
            if not picking.batch_id.picking_type_id:
                picking.batch_id.picking_type_id = picking.picking_type_id[0]
            picking.batch_id._sanity_check()

    return pickings

def write(self, vals):
    if vals.get('picking_type_id') and any(picking.state in ('done', 'cancel') for picking in self):
        raise UserError(_("Changing the operation type of this record is forbidden at this point."))

    old_batches = self.batch_id
    if vals.get('picking_type_id'):
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id'))
        for picking in self:
            if picking.picking_type_id != picking_type:
                picking.name = picking_type.sequence_id.next_by_id()
                vals['location_id'] = picking_type.default_location_src_id.id
                vals['location_dest_id'] = picking_type.default_location_dest_id.id
    res = super().write(vals)

    if vals.get('batch_id'):
        old_batches.filtered(lambda b: not b.picking_ids).state = 'cancel'
        if not self.batch_id.picking_type_id:
            self.batch_id.picking_type_id = self.picking_type_id[0]
        self.batch_id._sanity_check()
        # assign batch users to batch pickings
        self.batch_id.picking_ids.assign_batch_user(self.batch_id.user_id.id)
    if vals.get('date_done'):
        self.filtered(lambda p: p.state == 'done').move_ids.date = vals['date_done']
    if vals.get('signature'):
        for picking in self:
            picking._attach_sign()
    # Change locations of moves if those of the picking change
    after_vals = {}
    if vals.get('location_id'):
        after_vals['location_id'] = vals['location_id']
    if vals.get('location_dest_id'):
        after_vals['location_dest_id'] = vals['location_dest_id']
    if after_vals:
        self.move_ids.filtered(lambda move: move.location_dest_usage != 'inventory').write(after_vals)
    if vals.get('move_ids'):
        self._autoconfirm_picking()

    return res

def unlink(self):
    self.move_ids._action_cancel()
    self.with_context(prefetch_fields=False).move_ids.unlink()  # Checks if moves are not done
    return super().unlink()

def _track_log_get_default_subtype(self, init_values):
    if 'state' in init_values and self.state in ('done', 'cancel'):
        return self.env.ref('stock.mt_picking_state')
    return super()._track_log_get_default_subtype(init_values)

def do_print_picking(self):
    self.write({'printed': True})
    return self.env.ref('stock.action_report_picking').report_action(self)

def should_print_delivery_address(self):
    self.ensure_one()
    return self.move_ids and (self.move_ids[0].partner_id or self.partner_id) and self._is_to_external_location()

def _is_to_external_location(self):
    self.ensure_one()
    return self.picking_type_code == 'outgoing'

def action_confirm(self):
    self._check_company()
    if not self.env.context.get('skip_zero_demand_check') and not modules.module.current_test:
        # Check for zero demand moves before confirming
        zero_demand_moves = self.move_ids.filtered(lambda m: m.product_uom_qty <= 0)
        if zero_demand_moves:
            return self._action_generate_zero_demand_wizard()

    # call `_action_confirm` on every draft move
    self.move_ids.filtered(lambda move: move.state == 'draft')._action_confirm()

    # run scheduler for moves forecasted to not have enough in stock
    self.move_ids.filtered(lambda move: move.state not in ('draft', 'cancel', 'done'))._trigger_scheduler()

    if self.env.user.has_group('stock.group_stock_picking_batch'):
        for picking in self:
            picking._find_auto_batch()
    return True

def action_cancel(self):
    self.move_ids._action_cancel()
    self.write({'is_locked': True})
    self.filtered(lambda x: not x.move_ids).state = 'cancel'
    # Remove the cancelled operation from its batch if the batch has other active picking(s).
    for picking in self:
        if picking.batch_id and any(picking.state != 'cancel' for picking in picking.batch_id.picking_ids):
            picking.batch_id = None
    return True

def action_return(self):
    new_picking = self._create_return()
    return {
        'name': _('Returned Picking'),
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking',
        'res_id': new_picking.id,
        'view_mode': 'form',
        'context': self.env.context,
    }

def action_return_all(self):
    """ Set all the quantities in the return picking as the original picking's done quantities
    """
    self.ensure_one()
    if self.return_id:
        for return_move in self.move_ids.filtered(lambda m: m.state not in ('done', 'cancel')):
            orig_move = return_move.origin_returned_move_id
            quantity = orig_move.quantity
            for dest_move in orig_move.move_dest_ids - return_move:
                if not dest_move.origin_returned_move_id or dest_move.origin_returned_move_id != orig_move:
                    continue
                quantity -= dest_move.quantity
            quantity = return_move.uom_id.round(quantity)
            return_move.product_uom_qty = quantity

def action_clear_return(self):
    self.ensure_one()
    if self.return_id:
        self.move_ids.product_uom_qty = 0

def action_exchange(self):
    self.ensure_one()
    if self.return_id:
        new_picking = self._create_return()
        new_picking.move_ids.write({
        'origin_returned_move_id': False,
        'move_orig_ids': False,
        })
        new_picking.action_confirm()
        new_picking.action_assign()
        return {
            'name': _('Returned Picking'),
            'type': 'ir.actions.act_window',
            'res_model': 'stock.picking',
            'res_id': new_picking.id,
            'view_mode': 'form',
            'context': self.env.context,
        }

def action_next_transfer(self):
    next_transfers = self._get_next_transfers()

    if len(next_transfers) == 1:
        return {
            "type": "ir.actions.act_window",
            "res_model": "stock.picking",
            "views": [[False, "form"]],
            "res_id": next_transfers.id
        }
    return {
        'name': _('Next Transfers'),
        "type": "ir.actions.act_window",
        "res_model": "stock.picking",
        "views": [[False, "list"], [False, "form"]],
        "domain": [('id', 'in', next_transfers.ids)],
    }

def action_view_batch(self):
    self.ensure_one()
    return {
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking.batch',
        'res_id': self.batch_id.id,
        'view_mode': 'form',
    }

def _intercompany_unpack(self):
    if not self.env.user.has_group('stock.group_tracking_lot') or\
       not self.env['ir.config_parameter'].sudo().get_bool('stock.intercompany_auto_unpack'):
        return
    for picking in self:
        if not picking.partner_id:
            continue
        destination_company = self.env['res.company'].sudo().search([('partner_id', 'parent_of', picking.partner_id.id)], limit=1)
        if destination_company == picking.company_id:
            continue
        moves = picking.move_ids.filtered(lambda m: m.location_dest_id.usage == 'transit')
        moves.move_line_ids.result_package_id.unpack()

def _send_confirmation_email(self):
    subtype_id = self.env['ir.model.data']._xmlid_to_res_id('mail.mt_comment')
    for stock_pick in self.filtered(lambda p: p.company_id.stock_move_email_validation and p.picking_type_id.code == 'outgoing'):
        delivery_template = stock_pick.company_id.stock_mail_confirmation_template_id
        stock_pick.with_context(force_send=True).message_post_with_source(
            delivery_template,
            email_layout_xmlid='mail.mail_notification_light',
            subtype_id=subtype_id,
        )

def _check_move_lines_map_quant_package(self, package):
    return package._check_move_lines_map_quant(self.move_line_ids.filtered(lambda ml:
        ml.product_id.is_storable
        and (ml.package_id == package or ml.package_id in package.all_children_package_ids)))

def _get_entire_pack_location_dest(self, move_line_ids):
    location_dest_ids = move_line_ids.mapped('location_dest_id')
    if len(location_dest_ids) > 1:
        return False
    return location_dest_ids.id

def _is_single_transfer(self):
    # Overriden for batches.
    if self.env.user.has_group('stock.group_stock_picking_batch'):
        return len(self) == 1 or len(self.batch_id) == 1
    return len(self) == 1

def _check_entire_pack(self):
    """ This function check if entire packs are moved in the picking"""
    for package, package_move_lines in self.move_line_ids.grouped('package_id').items():
        if not package:
            continue
        pickings = package_move_lines.picking_id
        if pickings._is_single_transfer() and pickings._check_move_lines_map_quant_package(package):
            move_lines_to_pack = package_move_lines.filtered(lambda ml: not ml.result_package_id and ml.state not in ('done', 'cancel'))
            if package.package_type_id.package_use != 'reusable':
                move_lines_to_pack.write({
                    'result_package_id': package.id,
                    'is_entire_pack': True,
                })
    # If we move all packages within a package, we can consider that they keep their container as well
    self.move_line_ids.result_package_id._apply_package_dest_for_entire_packs()

def _get_lot_move_lines_for_sanity_check(self, none_done_picking_ids, separate_pickings=True):
    """ Get all move_lines with tracked products that need to be checked over in the sanity check.
        :param none_done_picking_ids: Set of all pickings ids that have no quantity set on any move_line.
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    def get_relevant_move_line_ids(none_done_picking_ids, picking):
        # Get all move_lines if picking has no quantity set, otherwise only get the move_lines with some quantity set.
        if picking.id in none_done_picking_ids:
            return picking.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids
        else:
            return get_line_with_done_qty_ids(picking.move_line_ids)

    def get_line_with_done_qty_ids(move_lines):
        # Get only move_lines that has some quantity set.
        return move_lines.filtered(lambda ml: ml.product_id.tracking in ['lot', 'serial'] and ml.picked and ml.uom_id.compare(ml.quantity, 0)).ids

    if separate_pickings:
        # If pickings are checked independently, get full/partial move_lines depending if each picking has no quantity set.
        lines_to_check_ids = [line_id for picking in self for line_id in get_relevant_move_line_ids(none_done_picking_ids, picking)]
    else:
        # If pickings are checked as one (like in a batch), then get only the move_lines with quantity across all pickings if there is at least one.
        if any(picking.id not in none_done_picking_ids for picking in self):
            lines_to_check_ids = get_line_with_done_qty_ids(self.move_line_ids)
        else:
            lines_to_check_ids = self.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids

    return self.env['stock.move.line'].browse(lines_to_check_ids)

def _sanity_check(self, separate_pickings=True):
    """ Sanity check for `button_validate()`
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    pickings_without_lots = self.browse()
    products_without_lots = self.env['product.product']
    pickings_without_moves = self.filtered(lambda p: not p.move_ids and not p.move_line_ids)
    precision_digits = self.env['decimal.precision'].precision_get('Product Unit')

    no_quantities_done_ids = set()
    pickings_without_quantities = self.env['stock.picking']
    for picking in self:
        has_pick = any(move.picked and move.state not in ('done', 'cancel') for move in picking.move_ids)
        if all(float_is_zero(move.quantity, precision_digits=precision_digits) for move in picking.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and (not has_pick or m.picked))):
            pickings_without_quantities |= picking

    pickings_using_lots = self.filtered(lambda p: p.picking_type_id.use_create_lots or p.picking_type_id.use_existing_lots)
    if pickings_using_lots:
        lines_to_check = pickings_using_lots._get_lot_move_lines_for_sanity_check(no_quantities_done_ids, separate_pickings)
        for line in lines_to_check:
            if not line.lot_name and not line.lot_id:
                pickings_without_lots |= line.picking_id
                products_without_lots |= line.product_id

    if not self._should_show_transfers():
        if pickings_without_moves:
            raise UserError(_("You can’t validate an empty transfer. Please add some products to move before proceeding."))
        if pickings_without_quantities:
            raise UserError(self._get_without_quantities_error_message())
        if pickings_without_lots:
            raise UserError(_('You need to supply a Lot/Serial number for products %s.', ', '.join(products_without_lots.mapped('display_name'))))
    else:
        message = ""
        if pickings_without_moves:
            message += _('Transfers %s: Please add some items to move.', ', '.join(pickings_without_moves.mapped('name')))
        if pickings_without_lots:
            message += _(
                '\n\nTransfers %(transfer_list)s: You need to supply a Lot/Serial number for products %(product_list)s.',
                transfer_list=pickings_without_lots.mapped('name'),
                product_list=products_without_lots.mapped('display_name'),
            )
        if message:
            raise UserError(message.lstrip())

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def action_split_transfer(self):
    if self.state == 'done':
        return
    if all(m.uom_id.is_zero(m.quantity) for m in self.move_ids):
        raise UserError(_("%s: Nothing to split. Fill the quantities you want in a new transfer in the done quantities", self.display_name))
    if all(m.uom_id.compare(m.quantity, m.product_uom_qty) == 0 for m in self.move_ids):
        raise UserError(_("%s: Nothing to split, all demand is done. For split you need at least one line not fully fulfilled", self.display_name))
    if any(m.uom_id.compare(m.quantity, m.product_uom_qty) > 0 for m in self.move_ids):
        raise UserError(_("%s: Can't split: quantities done can't be above demand", self.display_name))

    moves = self.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and m.quantity != 0)
    backorder_moves = moves._create_backorder()
    backorder_moves += self.move_ids.filtered(lambda m: m.quantity == 0)
    backorder = self._create_backorder(backorder_moves=backorder_moves, from_manual_backorder=True)
    backorder.message_post(
        body=self.env._('Split from %(original_picking_link)s.', original_picking_link=self._get_html_link())
    )
    return {
        'name': self.env._('Split Backorder'),
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking',
        'view_mode': 'form',
        'res_id': backorder.id,
    }

def _pre_action_done_hook(self):
    for picking in self:
        has_quantity = False
        has_pick = False
        for move in picking.move_ids:
            if move.quantity:
                has_quantity = True
            if move.location_dest_usage == 'inventory':
                continue
            if move.picked:
                has_pick = True
            if has_quantity and has_pick:
                break
        if has_quantity and not has_pick:
            picking.move_ids.picked = True
    if not self.env.context.get('skip_backorder'):
        pickings_to_backorder = self._check_backorder()
        if pickings_to_backorder:
            return pickings_to_backorder._action_generate_backorder_wizard(show_transfers=self._should_show_transfers())
    return True

def _should_show_transfers(self):
    """Whether the different transfers should be displayed on the pre action done wizards."""
    if self.batch_id:
        picking_ids_to_detach = self.env.context.get('pickings_to_detach') or []
        batch_pickings_count = len(self.batch_id.picking_ids) - len(picking_ids_to_detach)
        if len(self.batch_id) == 1 and len(self) == batch_pickings_count:
            return False
    return len(self) > 1

def _should_ignore_backorders(self):
    """ Checks if the `create_backorder` setting from the picking type should be ignored.
    """
    return bool(self.return_id)

def _get_without_quantities_error_message(self):
    """ Returns the error message raised in validation if no quantities are reserved.
    The purpose of this method is to be overridden in case we want to adapt this message.

    :return: Translated error message
    :rtype: str
    """
    return _(
        "Transfer trouble alert! Validating a zero quantity transfer? You're not moving invisible goods around are you?\n"
        "Set some quantities and let's get moving!"
    )

def _check_backorder(self):
    prec = self.env["decimal.precision"].precision_get("Product Unit")
    backorder_pickings = self.browse()
    for picking in self:
        if picking.picking_type_id.create_backorder != 'ask':
            continue
        if any(
                (move.product_uom_qty and not move.picked) or
                float_compare(move._get_picked_quantity(), move.product_uom_qty, precision_digits=prec) < 0
                for move in picking.move_ids
                if move.state != 'cancel'
        ):
            backorder_pickings |= picking
    return backorder_pickings

def _autoconfirm_picking(self):
    """ Automatically run `action_confirm` on `self` if one of the
    picking's move was added after the initial
    call to `action_confirm`. Note that `action_confirm` will only work on draft moves.
    """
    for picking in self:
        if picking.state in ('done', 'cancel'):
            continue
        if not picking.move_ids:
            continue
        if any(move.additional for move in picking.move_ids):
            picking.with_context(skip_zero_demand_check=True).action_confirm()
    to_confirm = self.move_ids.filtered(lambda m: m.state == 'draft' and m.quantity)
    to_confirm._action_confirm()

def _get_moves_to_backorder(self):
    self.ensure_one()
    return self.move_ids.filtered(lambda x: x.state not in ('done', 'cancel'))

def _create_backorder_picking(self):
    self.ensure_one()
    return self.copy({
        'name': '/',
        'move_ids': [],
        'move_line_ids': [],
        'backorder_id': self.id,
        'return_id': self.return_id.id,
    })

def _log_activity_get_documents(self, orig_obj_changes, stream_field, stream, groupby_method=False):
    """ Generic method to log activity. To use with
    _log_activity method. It either log on uppermost
    ongoing documents or following documents. This method
    find all the documents and responsible for which a note
    has to be log. It also generate a rendering_context in
    order to render a specific note by documents containing
    only the information relative to the document it. For example
    we don't want to notify a picking on move that it doesn't
    contain.

    :param dict orig_obj_changes: contain a record as key and the
        change on this record as value.
        eg: {'move_id': (new product_uom_qty, old product_uom_qty)}
    :param str stream_field: It has to be a field of the
        records that are register in the key of 'orig_obj_changes'
        eg: 'move_dest_ids' if we use move as record (previous example)
            - 'UP' if we want to log on the upper most ongoing
            documents.
            - 'DOWN' if we want to log on following documents.
    :param str stream: ``'UP'`` or ``'DOWN'``
    :param groupby_method: Only need when
        stream is 'DOWN', it should group by tuple(object on
        which the activity is log, the responsible for this object)
    """
    if self.env.context.get('skip_activity'):
        return {}
    move_to_orig_object_rel = {co: ooc for ooc in orig_obj_changes for co in ooc[stream_field]}
    origin_objects = self.env[next(iter(orig_obj_changes.keys()))._name].concat(orig_obj_changes.keys())
    # The purpose here is to group each destination object by
    # (document to log, responsible) no matter the stream direction.
    # example:
    # {'(delivery_picking_1, admin)': stock.move(1, 2)
    #  '(delivery_picking_2, admin)': stock.move(3)}
    visited_documents = {}
    if stream == 'DOWN':
        if groupby_method:
            grouped_moves = groupby(origin_objects.mapped(stream_field), key=groupby_method)
        else:
            raise AssertionError('You have to define a groupby method and pass them as arguments.')
    elif stream == 'UP':
        # When using upstream document it is required to define
        # _get_upstream_documents_and_responsibles on
        # destination objects in order to ascend documents.
        grouped_moves = {}
        for visited_move in origin_objects.mapped(stream_field):
            for document, responsible, visited in visited_move._get_upstream_documents_and_responsibles(self.env[visited_move._name]):
                if grouped_moves.get((document, responsible)):
                    grouped_moves[(document, responsible)] |= visited_move
                    visited_documents[(document, responsible)] |= visited
                else:
                    grouped_moves[(document, responsible)] = visited_move
                    visited_documents[(document, responsible)] = visited
        grouped_moves = grouped_moves.items()
    else:
        raise AssertionError('Unknown stream.')

    documents = {}
    for (parent, responsible), moves in grouped_moves:
        if not parent:
            continue
        moves = self.env[moves[0]._name].concat(moves)
        # Get the note
        rendering_context = {move: (orig_object, orig_obj_changes[orig_object]) for move in moves for orig_object in move_to_orig_object_rel[move]}
        if visited_documents:
            documents[(parent, responsible)] = rendering_context, visited_documents.values()
        else:
            documents[(parent, responsible)] = rendering_context
    return documents

def _log_less_quantities_than_expected(self, moves):
    """ Log an activity on picking that follow moves. The note
    contains the moves changes and all the impacted picking.

    :param dict moves: a dict with a move as key and tuple with
    new and old quantity as value. eg: {move_1 : (4, 5)}
    """
    def _keys_in_groupby(move):
        """ group by picking and the responsible for the product the
        move.
        """
        return (move.picking_id, move.product_id.responsible_id)

    def _render_note_exception_quantity(rendering_context):
        """ :param rendering_context:
        {'move_dest': (move_orig, (new_qty, old_qty))}
        """
        origin_moves = self.env['stock.move'].browse([move.id for move_orig in rendering_context.values() for move in move_orig[0]])
        origin_picking = origin_moves.mapped('picking_id')
        move_dest_ids = self.env['stock.move'].concat(rendering_context.keys())
        impacted_pickings = origin_picking._get_impacted_pickings(move_dest_ids) - move_dest_ids.mapped('picking_id')
        values = {
            'origin_picking': origin_picking,
            'moves_information': rendering_context.values(),
            'impacted_pickings': impacted_pickings,
        }
        return self.env['ir.qweb']._render('stock.exception_on_picking', values)

    documents = self._log_activity_get_documents(moves, 'move_dest_ids', 'DOWN', _keys_in_groupby)
    documents = self._less_quantities_than_expected_add_documents(moves, documents)
    self._log_activity(_render_note_exception_quantity, documents)

def _get_impacted_pickings(self, moves):
    """ This function is used in _log_less_quantities_than_expected
    the purpose is to notify a user with all the pickings that are
    impacted by an action on a chained move.
    param: 'moves' contain moves that belong to a common picking.
    return: all the pickings that contain a destination moves
    (direct and indirect) from the moves given as arguments.
    """

    def _explore(impacted_pickings, explored_moves, moves_to_explore):
        for move in moves_to_explore:
            if move not in explored_moves:
                impacted_pickings |= move.picking_id
                explored_moves |= move
                moves_to_explore |= move.move_dest_ids
        moves_to_explore = moves_to_explore - explored_moves
        if moves_to_explore:
            return _explore(impacted_pickings, explored_moves, moves_to_explore)
        else:
            return impacted_pickings

    return _explore(self.env['stock.picking'], self.env['stock.move'], moves)

def action_put_in_pack(self, *, package_id=False, package_type_id=False, package_name=False):
